SourceCode.Declaration:
/// <summary>
/// The class <c>UPSProductPricingAttributeProvider</c> is used to provide <c>UPSPricingAttributeEcoResAttribute</c> associated with product.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeProviderEcoResProductAttribute extends UPSPricingAttributeAbstractProvider implements UPSIPricingAttributeProvider
{

}

Method.Source:
public anytype getValueOfAttribute(Common _pricingObject, UPSIPricingAttribute _attribute)
{
    EcoResProductAttributeValueV2Entity productAttributeValue;
    SalesLine salesLine;
    EcoResProduct product;

    UPSPricingAttributeEcoResAttribute attr = _attribute;

    salesLine = _pricingObject as SalesLine;
    if (salesLine)
    {
        product = salesLine.inventTable().Product();
    }

    select productAttributeValue
        where productAttributeValue.AttributeName == attr.getName()
        && productAttributeValue.AttributeTypeName == attr.getAttributeType()
        && productAttributeValue.ProductNumber == product.DisplayProductNumber;

    return this.extractAttributeValue(productAttributeValue);
}

public Set getAllowedValues(UPSIPricingAttribute _attribute)
{
    UPSPricingAttributeEcoResAttribute attr = _attribute;

    if (attr.isEnumeration())
    {
        return super(_attribute);
    }

    // Product specific attribute. Attribute with Fixed-list == No.
    var ret = new Set(Types::String);
    EcoResProductAttributeValueV2Entity productAttrValue;
    while select productAttrValue
            where productAttrValue.AttributeName == attr.getName() 
        && productAttrValue.AttributeTypeName == attr.getAttributeType()
    {
        ret.add(any2Str(this.extractAttributeValue(productAttrValue)));
    }
    return ret;

}

public Query buildPricingObjectQuery(Query _query, UPSIPricingAttribute _pricingAttr, anytype _value, Map _qbdsMap = null)
{
    EcoResProductAttributeValueV2Entity productAttrValue;
    QueryBuildDataSource qbds;
    QueryBuildDataSource qbdsEcoResProduct;
    QueryBuildDataSource qbdsEcoResAttributeType;
    QueryBuildDataSource qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(InventTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(InventTable));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(InventTable), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(tableStr(EcoResProduct)))
    {
        qbdsEcoResProduct = _qbdsMap.lookup(tableStr(EcoResProduct));
    }
    else
    {
        qbdsEcoResProduct = qbdsRoot.addDataSource(tableNum(EcoResProduct));
        qbdsEcoResProduct.addLink(fieldNum(InventTable, Product), fieldNum(EcoResProduct, RecId));
        qbdsEcoResProduct.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(EcoResProduct), qbdsEcoResProduct);
        }
    }

    qbds = qbdsEcoResProduct.addDataSource(tableNum(EcoResProductAttributeValueV2Entity));
    QueryBuildLink qbl = qbds.addLink(fieldNum(EcoResProduct, DisplayProductNumber), fieldNum(EcoResProductAttributeValueV2Entity, ProductNumber));
    qbds.joinMode(JoinMode::ExistsJoin);

    // qbdsEcoResAttributeType = qbds.addDataSource(tableNum(EcoResAttributeType));
    // qbdsEcoResAttributeType.addLink(fieldNum(EcoResProductAttributeValueV2Entity, AttributeTypeName), fieldNum(EcoResAttributeType, Name));
    // qbdsEcoResAttributeType.joinMode(JoinMode::InnerJoin);

    UPSPricingAttributeEcoResAttribute attr = _pricingAttr;

    QueryBuildRange qbrName = qbds.addRange(fieldNum(EcoResProductAttributeValueV2Entity, AttributeName));
    qbrName.value(any2Str(attr.getName()));

    QueryBuildRange qbrType = qbds.addRange(fieldNum(EcoResProductAttributeValueV2Entity, AttributeTypeName));
    qbrType.value(any2Str(attr.getAttributeType()));

    QueryBuildRange qbrValue;
    switch (this.getAttributeType(_pricingAttr.getName()))
    {
        case AttributeDataType::Currency:
            qbrValue = qbds.addRange(fieldNum(EcoResProductAttributeValueV2Entity, CurrencyValue));
            break;
        case AttributeDataType::DateTime:
            qbrValue = qbds.addRange(fieldNum(EcoResProductAttributeValueV2Entity, DateTimeValue));
            break;
        case AttributeDataType::Decimal:
            qbrValue = qbds.addRange(fieldNum(EcoResProductAttributeValueV2Entity, DecimalValue));
            break;
        case AttributeDataType::Integer:
            qbrValue = qbds.addRange(fieldNum(EcoResProductAttributeValueV2Entity, IntegerValue));
            break;
        case AttributeDataType::Text:
            qbrValue = qbds.addRange(fieldNum(EcoResProductAttributeValueV2Entity, TextValue));
            break;
        case AttributeDataType::TrueFalse:
            qbrValue = qbds.addRange(fieldNum(EcoResProductAttributeValueV2Entity, BooleanValue));
            break;
        default:
            // TODO: handle default, error out maybe
            qbrValue = qbds.addRange(fieldNum(EcoResProductAttributeValueV2Entity, TextValue));
    }
    qbrValue.value(any2Str(_value));

    return _query;
}

private anytype extractAttributeValue(EcoResProductAttributeValueV2Entity _attrValue)
{
    if (_attrValue)
    {
        switch (this.getAttributeType(_attrValue.AttributeName))
        {
            case AttributeDataType::Currency:
                return num2Str(_attrValue.CurrencyValue, 0, 3, 1, 2);
            case AttributeDataType::DateTime:
                return datetime2Str(_attrValue.DateTimeValue);
            case AttributeDataType::Decimal:
                return num2Str(_attrValue.DecimalValue, 0, 3, 1, 2);
            case AttributeDataType::Integer:
                return int642Str(_attrValue.IntegerValue);
            case AttributeDataType::Text:
                return _attrValue.TextValue;
            case AttributeDataType::TrueFalse:
                return enum2Str(_attrValue.BooleanValue);
            default:
                return '';
       }
    }

    return '';
}
